pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);

        ExploitRecipient r = new ExploitRecipient();

        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool s, ) = address(c).call{value: amount}("");
        require(s);

        uint256 before = address(c).balance;
        require(before == amount);

        bool ok;
        try c.withdrawAll(address(r)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract ExploitRecipient {
    uint256 public sink;
    fallback() external payable {
        sink = sink + 1;
    }
}
